<?php

namespace App\Http\Controllers;

use App\Models\Book;
use App\Support\PatronImportReader;
use Carbon\Carbon;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Throwable;

/**
 * Admin / librarian: add many books at once from an Excel (.xlsx) or CSV sheet.
 *
 * - Additive only: an accession number that already exists is skipped, never overwritten.
 * - The upload is read in memory and discarded. Nothing is saved to storage.
 * - No file is generated by the system (the sample template is a static file).
 * - Reuses the same sheet reader as the patron import.
 */
class BookImportController extends Controller
{
    private const MAX_ROWS = 20000;

    /** Header text (letters and digits only, lowercase) -> field. */
    private const HEADERS = [
        'accessionnumber' => 'accession_number', 'accessionno' => 'accession_number', 'accession' => 'accession_number',
        'accno' => 'accession_number', 'accnumber' => 'accession_number', 'accessno' => 'accession_number', 'bookno' => 'accession_number',
        'title' => 'title', 'booktitle' => 'title',
        'author' => 'author', 'authors' => 'author', 'authorname' => 'author',
        'isbn' => 'isbn',
        'category' => 'category', 'categories' => 'category',
        'copies' => 'total_copies', 'totalcopies' => 'total_copies', 'noofcopies' => 'total_copies', 'quantity' => 'total_copies', 'qty' => 'total_copies',
        'availablecopies' => 'available_copies', 'available' => 'available_copies', 'availcopies' => 'available_copies',
        'subtitle' => 'subtitle',
        'statementofresponsibility' => 'statement_of_responsibility',
        'edition' => 'edition_statement', 'editionstatement' => 'edition_statement',
        'placeofpublication' => 'place_of_publication', 'place' => 'place_of_publication', 'publicationplace' => 'place_of_publication',
        'publisher' => 'publisher',
        'yearofpublication' => 'year_of_publication', 'year' => 'year_of_publication', 'yearpublished' => 'year_of_publication',
        'publicationyear' => 'year_of_publication', 'pubyear' => 'year_of_publication', 'copyright' => 'year_of_publication',
        'series' => 'series_statement', 'seriesstatement' => 'series_statement',
        'contenttype' => 'content_type', 'mediatype' => 'media_type', 'carriertype' => 'carrier_type',
        'extent' => 'extent', 'pages' => 'extent', 'pagination' => 'extent',
        'dimensions' => 'dimensions', 'size' => 'dimensions',
        'language' => 'language', 'lang' => 'language',
        'callnumber' => 'call_number', 'callno' => 'call_number', 'callnum' => 'call_number',
        'subjects' => 'subjects', 'subject' => 'subjects',
        'genre' => 'genre',
        'summary' => 'summary', 'abstract' => 'summary', 'description' => 'summary',
        'notes' => 'notes', 'remarks' => 'notes',
        'library' => 'library',
        'location' => 'location', 'shelf' => 'location', 'shelflocation' => 'location',
        'dateacquired' => 'date_acquired', 'acquired' => 'date_acquired', 'acquisitiondate' => 'date_acquired',
        'dealerdonor' => 'dealer_donor', 'donor' => 'dealer_donor', 'dealer' => 'dealer_donor',
        'price' => 'price', 'cost' => 'price',
    ];

    /** Fields saved as plain text (max length 255). */
    private const SHORT_TEXT = [
        'isbn', 'category', 'subtitle', 'statement_of_responsibility', 'edition_statement', 'place_of_publication',
        'publisher', 'series_statement', 'content_type', 'media_type', 'carrier_type', 'extent', 'dimensions',
        'language', 'call_number', 'genre', 'library', 'location', 'dealer_donor',
    ];

    /** Fields saved as long text (max length 5000). */
    private const LONG_TEXT = ['subjects', 'summary', 'notes'];

    public function create()
    {
        abort_unless(auth()->user()->canManage(), 403);

        return view('books.import');
    }

    public function store(Request $request)
    {
        abort_unless($request->user()->canManage(), 403);

        $request->validate([
            'file' => ['required', 'file', 'max:10240'],
        ], [
            'file.max' => 'The file is too big (10 MB max). Split it into smaller sheets.',
        ]);

        $extension = strtolower($request->file('file')->getClientOriginalExtension());

        if (! in_array($extension, ['xlsx', 'csv', 'txt'], true)) {
            return back()->withErrors(['file' => 'Please upload an Excel file (.xlsx) or a CSV file. Old .xls files: open and Save As .xlsx first.']);
        }

        try {
            $rows = PatronImportReader::rows($request->file('file')->getRealPath(), $extension);
        } catch (Throwable $e) {
            return back()->withErrors(['file' => $e->getMessage()]);
        }

        // First non-empty row is the header.
        $header = null;
        $body = [];

        foreach ($rows as $row) {
            if (collect($row['cells'])->filter(fn ($v) => $v !== '')->isEmpty()) {
                continue;
            }

            if ($header === null) {
                $header = $row['cells'];
                continue;
            }

            $body[] = $row;
        }

        if ($header === null) {
            return back()->withErrors(['file' => 'The file is empty.']);
        }

        $map = [];
        foreach ($header as $index => $text) {
            $key = preg_replace('/[^a-z0-9]/', '', strtolower((string) $text));

            if (isset(self::HEADERS[$key]) && ! in_array(self::HEADERS[$key], $map, true)) {
                $map[$index] = self::HEADERS[$key];
            }
        }

        if (! in_array('accession_number', $map, true) || ! in_array('title', $map, true)) {
            return back()->withErrors(['file' => 'The first row must have the headings "Accession Number" and "Title" (optional: Author, ISBN, Category, Copies, Publisher, Year, Call Number, Subjects and more). Use the sample template.']);
        }

        if (count($body) > self::MAX_ROWS) {
            return back()->withErrors(['file' => 'Too many rows (' . count($body) . '). The limit is ' . self::MAX_ROWS . ' per file. Split the sheet.']);
        }

        $existing = Book::pluck('accession_number')->map(fn ($v) => strtolower((string) $v))->flip()->all();
        $valid = [];
        $skipped = [];
        $now = now();

        foreach ($body as $row) {
            $data = [];
            foreach ($map as $index => $field) {
                $data[$field] = trim((string) ($row['cells'][$index] ?? ''));
            }

            $result = $this->cleanRow($data, $existing);

            if (is_string($result)) {
                $skipped[] = ['row' => $row['row'], 'acc' => $data['accession_number'] ?? '', 'title' => $data['title'] ?? '', 'reason' => $result];
                continue;
            }

            $existing[strtolower($result['accession_number'])] = true;
            $valid[] = $result + ['created_at' => $now, 'updated_at' => $now];
        }

        DB::transaction(function () use ($valid) {
            foreach (array_chunk($valid, 200) as $chunk) {
                Book::insert($chunk);
            }
        });

        return redirect()->route('books.import')->with('import_result', [
            'created' => count($valid),
            'skipped' => $skipped,
            'total'   => count($body),
        ]);
    }

    /**
     * Returns the full database row for one book, or an error text when the row must be skipped.
     * Every row has the same keys so many rows can be inserted at once.
     */
    private function cleanRow(array $data, array $existing): array|string
    {
        $acc = $data['accession_number'] ?? '';
        $title = $data['title'] ?? '';

        if ($acc === '' || $title === '') {
            return 'Accession number and title are both required.';
        }

        if (mb_strlen($acc) > 255 || mb_strlen($title) > 255) {
            return 'Accession number or title is too long.';
        }

        if (isset($existing[strtolower($acc)])) {
            return 'This accession number already exists (kept as is).';
        }

        $author = $data['author'] ?? '';
        if (mb_strlen($author) > 255) {
            return 'Author is too long.';
        }

        $total = 1;
        if (($data['total_copies'] ?? '') !== '') {
            $total = $this->wholeNumber($data['total_copies']);

            if ($total === null || $total > 9999) {
                return 'Copies "' . $data['total_copies'] . '" is not a whole number from 0 to 9999.';
            }
        }

        $available = $total;
        if (($data['available_copies'] ?? '') !== '') {
            $available = $this->wholeNumber($data['available_copies']);

            if ($available === null) {
                return 'Available copies "' . $data['available_copies'] . '" is not a whole number.';
            }

            if ($available > $total) {
                return 'Available copies (' . $available . ') cannot be more than total copies (' . $total . ').';
            }
        }

        $year = $data['year_of_publication'] ?? '';
        if (mb_strlen($year) > 20) {
            return 'Year of publication is too long (20 characters max).';
        }

        $price = null;
        if (($data['price'] ?? '') !== '') {
            $clean = str_ireplace(['₱', 'php', ',', ' '], '', $data['price']);

            if (! is_numeric($clean) || (float) $clean < 0 || (float) $clean > 99999999.99) {
                return 'Price "' . $data['price'] . '" is not a valid amount.';
            }

            $price = number_format((float) $clean, 2, '.', '');
        }

        $acquired = null;
        if (($data['date_acquired'] ?? '') !== '') {
            $acquired = $this->date($data['date_acquired']);

            if ($acquired === null) {
                return 'Date acquired "' . $data['date_acquired'] . '" is not a valid date. Use YYYY-MM-DD.';
            }
        }

        $row = [
            'accession_number'    => $acc,
            'title'               => $title,
            'author'              => $author !== '' ? $author : 'Unknown',
            'total_copies'        => $total,
            'available_copies'    => $available,
            'year_of_publication' => $year !== '' ? $year : null,
            'date_acquired'       => $acquired,
            'price'               => $price,
        ];

        foreach (self::SHORT_TEXT as $field) {
            $value = $data[$field] ?? '';

            if (mb_strlen($value) > 255) {
                return 'The "' . str_replace('_', ' ', $field) . '" text is too long (255 characters max).';
            }

            $row[$field] = $value !== '' ? $value : null;
        }

        foreach (self::LONG_TEXT as $field) {
            $value = $data[$field] ?? '';

            if (mb_strlen($value) > 5000) {
                return 'The "' . $field . '" text is too long (5000 characters max).';
            }

            $row[$field] = $value !== '' ? $value : null;
        }

        return $row;
    }

    /** "5" or "5.0" -> 5. Anything else (text, negative, decimals like 2.5) -> null. */
    private function wholeNumber(string $value): ?int
    {
        if (! is_numeric($value)) {
            return null;
        }

        $number = (float) $value;

        return ($number >= 0 && floor($number) === $number) ? (int) $number : null;
    }

    /** Accepts YYYY-MM-DD style dates and Excel's own date numbers. Returns YYYY-MM-DD or null. */
    private function date(string $value): ?string
    {
        try {
            if (is_numeric($value)) {
                // A bare number is only a date when it is one of Excel's own date numbers (about 1954 to 2119).
                return ((float) $value > 20000 && (float) $value < 80000)
                    ? Carbon::create(1899, 12, 30)->addDays((int) $value)->toDateString()
                    : null;
            }

            return Carbon::parse($value)->toDateString();
        } catch (Throwable) {
            return null;
        }
    }
}
